const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry Definitions for the three cities
  const beijing = ee.Geometry.Rectangle([116.0, 39.5, 117.0, 40.5]);
  const chongqing = ee.Geometry.Rectangle([106.0, 29.0, 107.0, 30.0]);
  const wuhan = ee.Geometry.Rectangle([114.0, 30.3, 114.7, 31.0]);

  const cities = {
    'Beijing': beijing,
    'Chongqing': chongqing, 
    'Wuhan': wuhan
  };

  // 2. Time periods
  const period1 = ['2020-01-01', '2020-01-20']; // Jan 1-20
  const period2 = ['2020-02-10', '2020-02-25']; // Feb 10-25

  // 3. Data Acquisition - Sentinel-5P NO2
  const no2Col = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2');

  function getNO2Mean(cityGeom, startDate, endDate) {
    const col = no2Col
      .filterDate(startDate, endDate)
      .filterBounds(cityGeom)
      .select('NO2_column_number_density');

    const count = col.size().getInfo();
    if (count === 0) return null;

    const meanImg = col.mean();
    const stats = meanImg.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: cityGeom,
      scale: 1000,
      maxPixels: 1e9
    });

    const meanVal = stats.get('NO2_column_number_density').getInfo();
    const pixelCount = meanImg.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: cityGeom,
      scale: 1000,
      maxPixels: 1e9
    }).get('NO2_column_number_density').getInfo();

    return {mean: meanVal, pixels: pixelCount, images: count};
  }

  // 4. Process all cities and periods
  let allDecreased = true;
  let hasData = true;

  for (const [cityName, geometry] of Object.entries(cities)) {
    const period1Data = getNO2Mean(geometry, period1[0], period1[1]);
    const period2Data = getNO2Mean(geometry, period2[0], period2[1]);

    if (!period1Data || !period2Data) {
      console.log(`${cityName}: Missing data for one or both periods`);
      hasData = false;
      continue;
    }

    if (period1Data.pixels === 0 || period2Data.pixels === 0) {
      console.log(`${cityName}: No valid pixels`);
      hasData = false;
      continue;
    }

    const change = ((period2Data.mean - period1Data.mean) / period1Data.mean * 100);
    console.log(`${cityName}: Jan=${period1Data.mean.toFixed(4)}, Feb=${period2Data.mean.toFixed(4)}, Change=${change.toFixed(1)}%`);

    if (period2Data.mean >= period1Data.mean) {
      allDecreased = false;
    }
  }

  // 5. Final determination
  if (!hasData) {
    console.log("<answer>C1</answer>");
  } else if (allDecreased) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
